const TOOL_VOICE = {"स्क्रीन पर जो लिखा है, उसे वैसा ही पढ़ो, आखिरी शून्य के साथ।":"342aba8c7999d3ec6c23.ogg","हर वज़न वैसा ही पढ़ा जैसा छपा था, और दो अलग लिखे उत्तरों पर भी डंडी बराबर रही।":"6f597f3f3090ff163f13.ogg","मुक्त खेल।":"ccabc6dc1689df81851d.ogg","पलड़े पर कोई भी वज़न रखो, फिर उसे साफ़ करो और डंडी देखो।":"eafd42744681411fa090.ogg","पलड़े पर एक वज़न रखा है और तराज़ू उसे स्क्रीन पर दिखाता है।":"ec63355b57b03f94fb72.ogg","पहले बिंदु निकलता है, और बचे हुए अंक ऊपर की संख्या बनाते हैं।":"ee7671714248ddbf1d96.ogg","स्क्रीन पर अंक गिनो, फिर अपने लिखे अंक गिनो।":"b2e50a92aa085fb5c2af.ogg","हर अंक साथ आता है।":"8f6753405b738116da22.ogg","सिर्फ़ बिंदु पीछे रह जाता है।":"8294b547cc919809d0e8.ogg","अंश वही अंक हैं जिनमें से दशमलव बिंदु हटा दिया गया है और कुछ और नहीं बदला।":"d82e2bbcc42eb9a4e60e.ogg","तुमने सीखा: बिंदु निकलता है और हर अंक रहता है।":"02fc98856f7d8eb8d352.ogg","पलड़े पर छह दशमलव तीन किलोग्राम है।":"4b4164ed41694b469e17.ogg","उसके भिन्न की ऊपर की संख्या क्या है?":"3253fb0c0579a6fbcc2a.ogg","स्क्रीन पर कितने अंक छपे हैं?":"0abbef0dec9e38778099.ogg","अगला वज़न आठ दशमलव चार किलोग्राम है।":"b9c889ab1b1747914b68.ogg","मुझे फिर से ऊपर की संख्या बताओ।":"013aa2194b55cb91efc3.ogg","क्या कोई अंक बिंदु के साथ पीछे रह गया?":"f4b558f5dd2a53ac7d58.ogg","इस वज़न में बिंदु से पहले दो अंक हैं।":"257c132835345750b49f.ogg","पंद्रह दशमलव सात की ऊपर की संख्या लिखो।":"c92dce3851e7c1956222.ogg","यहाँ बाईं ओर दो अंक हैं।":"c8cb0278f7332db06dd7.ogg","सब गिनो।":"9bf34d58b7d893e5af2f.ogg","इस बेंच को दोनों संख्याएँ चाहिए, ऊपर वाली और नीचे वाली।":"19bcf4b4dc6e88d3afcb.ogg","बिंदु के बाद के स्थान गिनो, फिर नीचे एक और उतने ही शून्य लिखो।":"2e0f49a430d9659aec68.ogg","तुमने कितने स्थान जलाए?":"32717a3c890784a17515.ogg","शून्य उतने ही होने चाहिए।":"95229011ce65b4386ca5.ogg","एक स्थान के लिए एक शून्य, दो स्थान के लिए दो शून्य।":"557437d99f5ceb2a30ec.ogg","हर यानी एक, और उसके बाद हर दशमलव स्थान के लिए एक शून्य।":"ad2ebe09fb5428aa00c0.ogg","तुमने सीखा: बिंदु के बाद हर स्थान के लिए नीचे एक शून्य।":"fc44b69ee270a1485054.ogg","पलड़े पर पैंतालीस दशमलव दो आठ किलोग्राम है।":"cc08b36d2842f4b7894b.ogg","नीचे की संख्या बनाओ और पूरा भिन्न बताओ।":"4874cc9232e1e1a466c9.ogg","यहाँ बिंदु के बाद कितने अंक हैं?":"88539a84e4698269d81c.ogg","अगला वज़न तीस दशमलव छह दो किलोग्राम है।":"317687ab5f126f392010.ogg","बेंच को इसी तरह चलाओ।":"bf7896eaaa76803a256c.ogg","बिंदु के बाद हर स्थान को एक-एक करके जलाओ।":"8866cbfdf2dff767d907.ogg","इस पलड़े पर सात दशमलव दो शून्य नौ किलोग्राम है।":"2a1e3989679352b817e5.ogg","स्थान गिनो, फिर उसे भिन्न में लिखो।":"533d607527ec2a505ce6.ogg","बनाने से पहले गिनती को आखिर तक ले जाओ।":"fda839ad6359642c0d57.ogg","इस स्क्रीन पर आखिर में शून्य है, और तराज़ू ने उसे जानबूझकर छापा है।":"703dead43c8f2bc90011.ogg","छपा हुआ शून्य भी अपने स्थान पर है, इसलिए उसे भी गिनो।":"6ef5b3664e45a736ff89.ogg","बिंदु से शुरू करके बाहर की ओर गिनो।":"2d99799df71d3cd7c565.ogg","आखिरी छपे अंक पर रुको।":"a73958a0a15fb57ffb01.ogg","शून्य भी एक स्थान पर खड़ा है।":"6172219722086fcbfb2a.ogg","यहाँ कुछ भी फ़ालतू नहीं है।":"426ec04942a03f6e812e.ogg","आखिर का शून्य अपना एक दशमलव स्थान लेता है, इसलिए हर में एक शून्य ज़्यादा आता है।":"8fdeac3005adf7522109.ogg","तुमने सीखा: आखिर में छपा शून्य अपना एक स्थान लेता है।":"eddc60e78736414bf01f.ogg","तराज़ू वज़न को एक दशमलव चार पाँच शून्य किलोग्राम छापता है।":"1f02645e256c9970db78.ogg","इसे भिन्न में लिखो।":"b6422abc1768c3402bc6.ogg","क्या वह आखिरी शून्य किसी स्थान पर है, या नहीं?":"6ed30da815dbc32e40e3.ogg","एक लेबल पर दो दशमलव छह शून्य मीटर लिखा है।":"b7f330ecc7f689011ac4.ogg","इसे जैसा है वैसा पढ़ो और उसका भिन्न लिखो।":"e817c3720cf9a627da08.ogg","यहाँ कुछ भी साफ़ नहीं किया गया।":"710a66415275dba57a20.ogg","लेबल पर असल में क्या छपा है?":"9367a058f7fe5ba12dbf.ogg","बेंच ने एक वज़न से यह भिन्न बनाया।":"eec08bcf4f4124cc795c.ogg","तराज़ू ने जो वज़न छापा था, उसे लिखो।":"3a6123988acbc76537bd.ogg","नीचे के शून्य गिनो।":"52de7399a3b64021018e.ogg","वे बताते हैं कि कितने स्थान हैं।":"550e003b36d37cca2d8a.ogg","पहले साफ़ करो दबाने पर आखिर का एक शून्य हट जाता है और बेंच फिर से चलती है।":"79ac8cef0da35f32a49d.ogg","देखो, डंडी बराबर रहती है जबकि दो लिखे उत्तर अलग-अलग हैं।":"204e14f95dc7221f679d.ogg","प्रश्न किस पंक्ति के बारे में था, छपी हुई या साफ़ की हुई?":"1e3b30149c11d6cd99e2.ogg","डंडी नहीं हिलेगी।":"76debe811f6764a3565b.ogg","पर लिखावट बदल जाती है।":"0e143d5f295457a20c8a.ogg","आखिर का शून्य मात्रा को नहीं बदलता, पर एक दशमलव स्थान लेता है।":"e25308986ddd6f6aa9a8.ogg","यह हर को बदलता है, वज़न को नहीं।":"b5b88785270b550e8cf7.ogg","तुमने सीखा: वही मात्रा भी अलग लिखा हुआ उत्तर हो सकती है।":"55ef0bdd0ccfcf24b13e.ogg","उसी एक दशमलव चार पाँच शून्य किलोग्राम वज़न को पहले साफ़ करो, फिर भिन्न बनाओ।":"c7cafd887da92423d09f.ogg","क्या निकलता है?":"e84daed402a8bb33361c.ogg","आखिर का शून्य हटने पर कितने स्थान बचते हैं?":"80ee9964e978858fbb4b.ogg","एक ऊँचाई एक दशमलव तीन शून्य मीटर छपी है।":"68921080180c4ef303a3.ogg","छपे हुए रूप का भिन्न लिखो।":"ac634038fab985f7b599.ogg","प्रश्न छपी हुई पंक्ति के बारे में है।":"72c8b0a563000f0d115c.ogg","एक थैले पर पाँच दशमलव दो पाँच शून्य किलोग्राम छपा है।":"4d0afdb55045f9ccdd97.ogg","इसे जैसा है वैसा बदलो, आखिर के शून्य के साथ।":"ee207b381073a2d08a55.ogg","क्या तुमने तराज़ू के छापे आखिरी शून्य को गिना?":"6482ba8128bb085ee326.ogg","સ્ક્રીન પર જે લખ્યું છે તે એમ જ વાંચો, છેલ્લા શૂન્ય સાથે.":"dc1150494c8dad8f0b76.ogg","દરેક વજન જેવું છપાયું હતું તેવું જ વાંચ્યું,":"560b70a4e620cb21a7a4.ogg","અને બે અલગ લખેલા જવાબો છતાં દાંડી સમતોલ રહી.":"dd8e95dd0f80478d2e66.ogg","મુક્ત રમત.":"bcfc14c1819f3e6a51cd.ogg","પલ્લા પર કોઈ પણ વજન મૂકો, પછી તેને સાફ કરો અને દાંડી જુઓ.":"21e16b151fda17feb69b.ogg","પલ્લા પર એક વજન મૂકેલું છે અને વજનકાંટો તેને સ્ક્રીન પર બતાવે છે.":"3c6b329706df7edc2c2e.ogg","પહેલા બિંદુ નીકળે છે, અને બાકી રહેલા અંકો ઉપરની સંખ્યા બનાવે છે.":"dea4b2c3921889ba4c82.ogg","સ્ક્રીન પરના અંકો ગણો, પછી તમે લખેલા અંકો ગણો.":"b1acf32caa2dc23143b5.ogg","દરેક અંક સાથે આવે છે.":"0fab0ac8102751d41ab6.ogg","ફક્ત બિંદુ પાછળ રહી જાય છે.":"92c6b728ce3b3aa209c6.ogg","અંશ એટલે દશાંશ ચિહ્ન કાઢી નાખ્યા પછીના અંકો, બીજું કંઈ બદલાયા વિના.":"a0f40858093851236987.ogg","તમે શીખ્યા: બિંદુ નીકળે છે અને દરેક અંક રહે છે.":"2afd16bfeda642b346a3.ogg","પલ્લા પર છ દશાંશ ત્રણ કિલોગ્રામ છે.":"9ae730c584b403df2941.ogg","તેના અપૂર્ણાંકની ઉપરની સંખ્યા શું છે?":"df060a0764a17947f07e.ogg","સ્ક્રીન પર કેટલા અંકો છપાયા છે?":"7c40e20f266314bc4495.ogg","હવે પછીનું વજન આઠ દશાંશ ચાર કિલોગ્રામ છે.":"14efca55c59b79bd606c.ogg","ફરી ઉપરની સંખ્યા કહો.":"364297e028b5d0ade32f.ogg","શું કોઈ અંક બિંદુ સાથે પાછળ રહી ગયો?":"1943d92ea3773ecf14a7.ogg","આ વજનમાં બિંદુ પહેલાં બે અંકો છે.":"fbce0d35f22505037fe1.ogg","પંદર દશાંશ સાત ની ઉપરની સંખ્યા લખો.":"5f8cfec3781028d1691d.ogg","અહીં ડાબી બાજુ બે અંકો છે.":"353035c90b93592cf49b.ogg","બધા ગણો.":"40703e38e84474cb8b54.ogg","આ બેન્ચને બંને સંખ્યાઓ જોઈએ, ઉપરની અને નીચેની.":"82b0c415682fdeaceb28.ogg","બિંદુ પછીના સ્થાનો ગણો, પછી નીચે એક અને તેટલા જ શૂન્ય લખો.":"7aec62fee7a505398d1e.ogg","તમે કેટલા સ્થાન ચમકાવ્યા?":"e0aa34231c8c29824139.ogg","શૂન્ય તેટલા જ હોવા જોઈએ.":"4b04c13ed85b1fa52a52.ogg","એક સ્થાન માટે એક શૂન્ય, બે સ્થાન માટે બે શૂન્ય.":"32303834bbdd2a7f3144.ogg","છેદ એટલે એક, અને તેની પછી દરેક દશાંશ સ્થાન માટે એક શૂન્ય.":"f99fdb5af9dbb7aae437.ogg","તમે શીખ્યા: બિંદુ પછીના દરેક સ્થાન માટે નીચે એક શૂન્ય.":"99732a89c00c7b91c26d.ogg","પલ્લા પર પિસ્તાલીસ દશાંશ બે આઠ કિલોગ્રામ છે.":"0a7bb89942a5531b680c.ogg","નીચેની સંખ્યા બનાવો અને આખો અપૂર્ણાંક કહો.":"2db2547b70e7a11fab64.ogg","અહીં બિંદુ પછી કેટલા અંકો છે?":"48a1d1d1b42ffa56b6fa.ogg","હવે પછીનું વજન ત્રીસ દશાંશ છ બે કિલોગ્રામ છે.":"3058df6763f3344a0fa2.ogg","બેન્ચ પર એ જ રીતે કરો.":"e93f33c9bae78e476566.ogg","બિંદુ પછીના દરેક સ્થાનને એક પછી એક ચમકાવો.":"70153c5a89c62d67a941.ogg","આ પલ્લા પર સાત દશાંશ બે શૂન્ય નવ કિલોગ્રામ છે.":"8b8a31b8b7350a000326.ogg","સ્થાનો ગણો, પછી અપૂર્ણાંક તરીકે લખો.":"8673ae19df91867043b4.ogg","બનાવતા પહેલાં ગણતરી છેલ્લે સુધી ચલાવો.":"442636275ee3a8422d6f.ogg","આ સ્ક્રીન પર છેલ્લે શૂન્ય છે, અને વજનકાંટાએ તેને જાણી જોઈને છાપ્યું છે.":"30bf75f88317f9b72ffd.ogg","છપાયેલું શૂન્ય પણ પોતાના સ્થાને છે, એટલે તેને પણ ગણો.":"5ab2968101a1be75945d.ogg","બિંદુથી શરૂ કરીને બહાર તરફ ગણો.":"2d23bae6931b86530ccf.ogg","છેલ્લા છપાયેલા અંક પર અટકો.":"24ba6fa85487fbc71a38.ogg","શૂન્ય પણ એક સ્થાન પર ઊભું છે.":"b98423e7758ff24b8e23.ogg","અહીં કંઈ વધારાનું નથી.":"9605c59f876d36ea2e27.ogg","છેલ્લું શૂન્ય પોતાનું એક દશાંશ સ્થાન લે છે, એટલે છેદમાં એક શૂન્ય વધુ આવે છે.":"f7947eb349aed1a1b1b5.ogg","તમે શીખ્યા: છેલ્લે છપાયેલું શૂન્ય પોતાનું એક સ્થાન લે છે.":"e4ef2d46a613badf3152.ogg","વજનકાંટો વજન એક દશાંશ ચાર પાંચ શૂન્ય કિલોગ્રામ છાપે છે.":"40ad350d5d38997f442a.ogg","તેને અપૂર્ણાંક તરીકે લખો.":"13502685d120ff45ff95.ogg","શું તે છેલ્લું શૂન્ય કોઈ સ્થાન પર છે, કે નહીં?":"ffa8fde9e72ef6977b48.ogg","એક લેબલ પર બે દશાંશ છ શૂન્ય મીટર લખ્યું છે.":"c0c3ad18ff3e4e40cdda.ogg","તેને જેમ છે તેમ વાંચો અને તેનો અપૂર્ણાંક લખો.":"ad6cf1f078fa30b5f7f1.ogg","અહીં કંઈ સાફ કર્યું નથી.":"bc77f71dcec71b574894.ogg","લેબલ પર ખરેખર શું છપાયું છે?":"40a3bbc741402cef20da.ogg","બેન્ચે એક વજનમાંથી આ અપૂર્ણાંક બનાવ્યો.":"00733b9cecb941a3659a.ogg","વજનકાંટાએ જે વજન છાપ્યું હતું તે લખો.":"dd93194e5cfce1828aef.ogg","નીચેના શૂન્ય ગણો.":"f65807f3bfc2b3b08088.ogg","તે કહે છે કે કેટલા સ્થાન છે.":"119754546ae2394d6932.ogg","પહેલાં સાફ કરો દબાવતાં છેલ્લું એક શૂન્ય નીકળી જાય છે અને બેન્ચ ફરી ચાલે છે.":"1d1282f36dbd0f4ed889.ogg","જુઓ, બે લખેલા જવાબો અલગ છે છતાં દાંડી સમતોલ રહે છે.":"3bef39677432ed37ea0e.ogg","પ્રશ્ન કઈ હરોળ વિશે હતો, છપાયેલી કે સાફ કરેલી?":"5109e9106d674da936f8.ogg","દાંડી હલશે નહીં.":"2f78992f169f5d10dac5.ogg","પણ લખાણ બદલાય છે.":"892dec43927b79f847e6.ogg","છેલ્લું શૂન્ય જથ્થાને બદલતું નથી, પણ એક દશાંશ સ્થાન લે છે.":"d509da7d81db33538a0b.ogg","તે છેદ બદલે છે, વજન નહીં.":"e16419523ab8a691d2fe.ogg","તમે શીખ્યા: એ જ જથ્થો પણ અલગ લખેલો જવાબ હોઈ શકે.":"746dfcfe6c3c650c27e5.ogg","એ જ એક દશાંશ ચાર પાંચ શૂન્ય કિલોગ્રામ વજનને પહેલાં સાફ કરો, પછી અપૂર્ણાંક બનાવો.":"6f7525d2b21b717be65b.ogg","શું આવે છે?":"31f3c6927ede95206398.ogg","છેલ્લું શૂન્ય જતાં કેટલા સ્થાન બચે છે?":"f1e1d3f926fcea158c99.ogg","એક ઊંચાઈ એક દશાંશ ત્રણ શૂન્ય મીટર છપાયેલી છે.":"1e08687ec53d00b400f4.ogg","છપાયેલા રૂપનો અપૂર્ણાંક લખો.":"6b9941abe3bf26d130d1.ogg","પ્રશ્ન છપાયેલી હરોળ વિશે છે.":"7a93e68041faf6e16fbb.ogg","એક થેલી પર પાંચ દશાંશ બે પાંચ શૂન્ય કિલોગ્રામ છપાયું છે.":"6f7e52002d20b9476fdb.ogg","તેને જેમ છે તેમ બદલો, છેલ્લા શૂન્ય સાથે.":"2f29f7ebb1b3a2833cb4.ogg","શું તમે વજનકાંટાએ છાપેલું છેલ્લું શૂન્ય ગણ્યું?":"508fd6d7bf3c1f704e84.ogg"};
